{
  "headline": "FDA's records trace our supply to a plant classified OAI 257 days before the posting",
  "headline_cites": ["E15", "D1"],
  "sentences": [
    {
      "text": "The label for our acyclovir sodium product names Aurobindo Pharma Limited as the manufacturing plant, which was classified OAI on 2026-02-06.",
      "cites": ["E15"]
    },
    {
      "text": "That OAI classification occurred 257 days before the posting date of 2026-10-21.",
      "cites": ["E15", "D1"]
    },
    {
      "text": "The same facility, operating as Eugia Pharma Specialities Limited, received a Warning Letter on 2024-08-15 and another OAI classification on 2024-02-02.",
      "cites": ["E11", "E14"]
    },
    {
      "text": "A recall by AuroMedics Pharma LLC for particulate matter in acyclovir sodium injection was initiated on 2022-09-26 and completed.",
      "cites": ["E29"]
    },
    {
      "text": "Corvale East has 39 days of supply on hand, Corvale General has 17 days, and Corvale Lakeside has 25 days.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The best option by rule is to buy from Eugia US LLC, which is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["E15"]
    }
  ]
}
